"""Original20 vector item symbols, Android resources and OFL font subset. No network."""
from pathlib import Path
import json,html
from fontTools.ttLib import TTFont
from fontTools import subset
R=Path(__file__).resolve().parents[1];O=R/'art/source/items-1.66'
# Each symbol is independently drawn, with shared48px viewport/stroke for readability.
DATA=[('增殖核心', 'Twin Seed', '当前粒子数翻倍；空间或108000总上限不足时，只增加实际放得下的数量。', 'Double your army; limited by free space and the108000 global cap.', '#FFD780', 'M8,20 A7,7 0,1 1,22,20 A7,7 0,1 1,8,20 M26,28 A7,7 0,1 1,40,28 A7,7 0,1 1,26,28 M24,8 L24,15 M20,11 L28,11'), ('噬岩之牙', 'Stone Eater', '持续12秒，接触内部障碍时啃开地形，每格增加1颗粒子；触顶后仍开路但不增兵，外边框不可破坏。', 'For12s, chew contacted interior walls into one particle per cell; at the cap, walls still open without adding troops. Borders stay solid.', '#EBC397', 'M8,12 L19,8 L29,15 L40,10 L36,34 L27,40 L21,25 L15,38 Z M8,12 L21,25 L29,15'), ('时间冻结', 'Time Freeze', '让所有敌队停止移动和主动攻击10秒，仍可被吞噬；暖流可解除。', 'Freeze all enemies for10s. They remain vulnerable. Thaw counters it.', '#9FE6FF', 'M24,5 L24,43 M8,14 L40,34 M8,34 L40,14 M17,7 L24,14 L31,7 M17,41 L24,34 L31,41 M11,17 L17,23 L10,28 M37,17 L31,23 L38,28'), ('瞬间移动', 'Blink Gate', '拾取后点选地面，将整队传送到该处。落墙、空间不足或被空间锚限制时保留选择，可重选。', 'Select floor to teleport the whole army. Invalid or blocked destinations retain the choice.', '#C1A7FF', 'M15,7 A10,17 0,1 0,15,41 M33,7 A10,17 0,1 1,33,41 M12,24 L36,24 M29,17 L36,24 L29,31'), ('重置时间', 'Time Rewind', '整局回到开局：恢复粒子、生命、地图、联盟及计时，重新倒数3秒；因果锁可阻止。', 'Restore initial armies, health, terrain, alliances and match time, then count down3s. Causal Lock blocks it.', '#D0BEFF', 'M10,13 A17,17 0,1 1,7,27 M10,6 L10,16 L20,16 M24,12 L24,25 L16,30'), ('无障碍穿行', 'Phase Walk', '持续12秒可穿过内部障碍，外框不穿。结束时墙内粒子移到附近空地；相位钉可中断。', 'Pass through interior walls for12s. Expiry moves embedded particles to free floor. Phase Nail interrupts it.', '#D9A8FF', 'M9,8 L19,8 L19,40 L9,40 M29,8 L39,8 L39,40 L29,40 M5,24 L43,24 M36,17 L43,24 L36,31'), ('无敌时间', 'Invincible Time', '持续20秒免疫吞噬与指定淘汰；仍会被冻结。破盾裁决可解除并压制。', 'Immune to capture and Death Time for20s. Freeze still applies. Shatter removes it.', '#FFE39B', 'M24,4 L40,12 L37,30 L24,43 L11,30 L8,12 Z M17,24 L22,29 L32,17 M24,9 L24,13'), ('死亡时间', 'Death Time', '拾取后选择一个存活敌队直接淘汰。无敌可挡住；替命符抵消一次并消耗双方道具。', 'Select a living enemy to eliminate. Invincibility blocks it; Death Ward cancels one attempt.', '#FF899F', 'M13,9 L35,9 L39,27 L31,33 L31,41 L17,41 L17,33 L9,27 Z M17,21 L20,24 M31,21 L28,24 M23,30 L25,30 M22,35 L22,41 M27,35 L27,41'), ('朋友时间', 'Friend Time', '选择一个存活敌队，双方整个联盟合并，互不吞噬。独立宣言可解除道具结盟并暂时阻止。', 'Select a living enemy to merge both alliances. Declaration restores initial allies and temporarily blocks merging.', '#9FE2BB', 'M24,39 Q3,25 9,13 Q17,4 24,14 Q31,4 39,13 Q45,25 24,39 Z M16,23 L21,28 L32,18'), ('抑制增殖', 'Mass Balance', '持续20秒，敌方翻倍与吃墙均不能增加粒子；已经增加的粒子保留。', 'For20s, enemies cannot add particles through doubling or wall eating. Existing growth remains.', '#FFB67E', 'M9,15 A7,7 0,1 1,23,15 A7,7 0,1 1,9,15 M25,33 A7,7 0,1 1,39,33 A7,7 0,1 1,25,33 M8,40 L40,8'), ('岩层封印', 'Lithic Seal', '持续20秒阻止敌方啃墙，已有缺口保留；封印结束后，尚未到期的噬岩可继续。', 'For20s, enemies cannot chew walls. Existing openings remain.', '#83C7EB', 'M7,11 L20,7 L27,16 L40,11 L38,39 L10,40 Z M16,26 L32,26 L32,36 L16,36 Z M20,26 L20,21 A4,4 0,0 1,28,21 L28,26'), ('破冰暖流', 'Thaw Current', '立即解除己方及盟友冻结，并获得20秒冻结免疫。冻结时接触到它也能拾取。', 'Thaw yourself and allies, with20s freeze immunity. Can be collected while frozen.', '#FFCA8A', 'M26,5 Q34,18 29,24 Q39,19 40,29 A16,13 0,0 1,8,29 Q7,19 18,11 Q14,24 21,27 Q25,20 26,5 Z'), ('空间锚', 'Spatial Anchor', '持续20秒，所有敌队不能执行瞬间移动；其传送选择保留至限制解除。', 'For20s, enemies cannot teleport. Their pending choice remains available afterward.', '#8DD9E7', 'M20,10 A4,4 0,1 1,28,10 A4,4 0,1 1,20,10 M24,14 L24,40 M13,22 L35,22 M7,29 Q8,40 24,42 Q40,40 41,29 M7,29 L7,36 M41,29 L41,36'), ('因果锁', 'Causal Lock', '持续20秒，敌队的重置时间无法生效；被阻止的重置道具会消耗并显示提示。', 'For20s, enemy rewind pickups are consumed without rewinding, with explicit blocked feedback.', '#C9C2FF', 'M11,11 A17,17 0,1 1,6,26 M11,5 L11,15 L21,15 M20,26 L34,26 L34,38 L20,38 Z M23,26 L23,21 A4,4 0,0 1,31,21 L31,26'), ('相位钉', 'Phase Nail', '立即消除敌方穿墙，将墙内粒子安全移出，并压制20秒；原穿墙效果不恢复。', 'End enemy phasing, safely eject embedded particles, and block phasing for20s.', '#A6AEFF', 'M15,6 L33,6 L33,13 L27,13 L27,34 L24,43 L21,34 L21,13 L15,13 Z M6,23 L16,23 M32,23 L42,23'), ('破盾裁决', 'Shieldbreaker', '立即消除敌方无敌，并压制20秒；压制结束后原无敌不恢复。', 'Remove enemy invincibility and prevent it for20s.', '#FFAE9A', 'M24,5 L40,12 L37,29 L24,42 L11,29 L8,12 Z M28,8 L20,23 L29,23 L20,40 M5,35 L13,29 M35,20 L43,14'), ('替命符', 'Death Ward', '为自己保留一次指定淘汰抵挡，触发后符印破碎；普通吞噬不触发，重复拾取不叠加。', 'Block one Death Time attempt. Does not block ordinary combat. Extra wards do not stack.', '#F0D49A', 'M12,5 L30,5 L37,12 L37,42 L12,42 Z M30,5 L30,13 L37,13 M18,20 L31,20 M24,17 L24,33 M18,27 L30,27 M19,36 L29,36'), ('独立宣言', 'Declaration', '自己和开局盟友退出后续合并的联盟，恢复为一组；其他队伍关系不变。该组20秒内免疫朋友时间。', 'Restore your initial allies and protect that alliance from forced merging for20s.', '#B9E3D1', 'M12,43 L12,6 L37,10 L32,21 L12,19 M23,27 L31,35 M31,27 L23,35')]
def main():
 O.mkdir(parents=True,exist_ok=True)
 rows=[]
 for i,(zh,en,desc,eng,color,path) in enumerate(DATA):
  if i>=9:desc="克制"+DATA[i-9][0]+"。"+desc;eng="Counters "+DATA[i-9][1]+". "+eng
  rows.append(dict(id=i,name_zh=zh,name_en=en,description_zh=desc,description_en=eng,color=color,path=path,source='Original programmatic vector artwork,2026-11-07',license='GPL-3.0-or-later'))
  svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48"><path d="{path}" fill="none" stroke="{color}" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>\n'
  (O/f'{i:02}.svg').write_text(svg,encoding='utf8')
  (R/f'app/src/main/res/drawable/item_{i:02}.xml').write_text(f'<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="48dp" android:height="48dp" android:viewportWidth="48" android:viewportHeight="48"><path android:pathData="{path}" android:fillColor="#00000000" android:strokeColor="{color}" android:strokeWidth="2.6" android:strokeLineCap="round" android:strokeLineJoin="round"/></vector>',encoding='utf8')
 (O/'catalog.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf8')
 for folder,lang in [('values','en'),('values-zh','zh')]:
  xml=['<?xml version="1.0" encoding="utf-8"?>','<resources>']
  for key,field in [('item_names','name_'),('item_descriptions','description_')]:
   xml.append(f'<string-array name="{key}">');xml +=['<item>'+html.escape(row[field+lang]).replace("'","\\'")+'</item>' for row in rows];xml.append('</string-array>')
  xml.append('</resources>');(R/f'app/src/main/res/{folder}/items.xml').write_text('\n'.join(xml),encoding='utf8')
 # Retain all existing subset glyphs, and add every newly rendered character.
 old=TTFont(R/'app/src/main/assets/fonts/NotoSansSC-Intro.ttf');chars=set(old.getBestCmap());old.close()
 chars.update(map(ord,''.join(str(v) for r in rows for v in r.values())+'道具图鉴每次随机刷新两件触碰拾取暂停时计时冻结当前效果下次刷新秒已获得增加粒子已满无空间暂未生效观战总数详情返回关闭翻倍上限净化保护找到你队伍'))
 for p in (R/'app/src/main/java').rglob('Item*.java'):chars.update(map(ord,p.read_text('utf8')))
 font=TTFont(R/'art/source/free-maps-1.60/fonts/NotoSansSC-VF.ttf');opts=subset.Options();ss=subset.Subsetter(options=opts);ss.populate(unicodes=chars);ss.subset(font);font.save(R/'app/src/main/assets/fonts/NotoSansSC-Intro.ttf')
 (O/'README.md').write_text('18个用户道具及克制矢量图标及中英文规则；GPL-3.0-or-later。字体Noto Sans SC，SIL OFL1.1；完整原件与许可在../free-maps-1.60/fonts。build_item_assets.py可重新导出。图标48×48透明画布，pivot中心，无动画帧；运行使用Android VectorDrawable，不是效果截图。',encoding='utf8')
 print('Exported18 original vectors/resources and extended OFL font subset')
if __name__=='__main__':main()
